  const show=(all=false)=>{const q=all?'':input.value.normalize('NFKC').toLocaleLowerCase();matches=entries.filter(p=>p.id&&p.search.includes(q));active=matches.length?0:-1;list.innerHTML=matches.length?matches.map((p,i)=>'<button type="button" role="option" tabindex="-1" id="'+uid+'-'+i+'" data-teacher-option="'+i+'">'+esc(p.name)+'</button>').join(''):'<div class="hint">No matching teacher</div>';list.querySelectorAll('[data-teacher-option]').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>choose(matches[Number(b.dataset.teacherOption)]);});list.hidden=false;input.setAttribute('aria-expanded','true');mark();};
  input.value=id?name():'';value.value=id||'';
