  input.disabled=!people.length;input.placeholder=people.length?'Search and add teachers':'Loading teacher names…';const validate=()=>input.setCustomValidity(required&&!selected.length?'Select at least one absent teacher.':required&&selected.some(id=>!people.some(p=>p.id===id))?'Remove teachers who are no longer eligible before continuing.':'');
