  function renderChips(){chips.innerHTML=selected.map(id=>{const person=people.find(p=>p.id===id)||{name:id};return '<button type="button" class="teacher-chip" data-staff="'+esc(id)+'" aria-label="Remove '+esc(person.name)+'">'+esc(person.name)+' <span aria-hidden="true">×</span></button>';}).join('');chips.querySelectorAll('button').forEach(b=>b.onclick=()=>toggle(b.dataset.staff));}
  input.oninput=()=>{highlighted=-1;choices();list.hidden=false;input.setAttribute('aria-expanded','true');};input.onfocus=()=>{choices();list.hidden=false;input.setAttribute('aria-expanded','true');};
