  const form=body.querySelector('form'),area=body.querySelector('[data-instructions-area]');if(coverageMode){body.querySelector('[data-select-periods]').hidden=true;body.querySelector('[data-clear-periods]').hidden=true;body.querySelector('[data-period-picker]').nextElementSibling.textContent=s.data.reportFormOnly?'Choose your periods when the timings are ready.':'Period timings are not available for this date. Choose full day or enter start and end times, then review your absence below.';}
